    FileSystem fs,
    String segmentPath,
    List<String> allLines,
    List<SessionRecord?> parsed,
    List<SessionRecord> entries,
    Set<String> seenRecordIds,
  ) async {
    final sw = Stopwatch()..start();
    final goodLines = <String>[allLines.first];
    final tornLines = <String>[];
    var duplicates = 0;
