///
/// Semantics:
/// - `unknown` (a `QuotaFetchResult` with a null quota and a one-line
///   reason) is DISTINCT from `unmetered` (a real `ProviderQuota` with
///   `isUnmetered: true`): unknown means "we could not ask", unmetered
///   means "there is no billing surface".
/// - A null `limit` means the provider tracks usage but caps nothing
///   (prepaid / unlimited); rendering shows `no cap` / `unlimited`, and
///   such providers are never depleted.
library;

import 'package:http/http.dart' as http;

/// Unit a provider's allowance is measured in.
enum QuotaUnit {
  currencyUsd('currencyUsd'),
  requests('requests'),
  tokens('tokens'),
  unmetered('unmetered');

  const QuotaUnit(this.value);

  /// The JSON name written by [toJson] — a pinned literal, so renaming
  /// the identifier cannot silently change persisted values.
  final String value;

  String toJson() => value;

  /// Tolerant parse: null/unknown falls back to [currencyUsd] (the
  /// historical default — quota reads must never crash on a future or
  /// corrupted unit spelling).
  static QuotaUnit fromJson(Object? value) => switch (value) {
    'requests' => requests,
    'tokens' => tokens,
    'unmetered' => unmetered,
    _ => currencyUsd,
  };
}

/// A provider's remaining-allowance snapshot at [updatedAt].
class ProviderQuota {
  final double? used;
  final double? limit;
  final QuotaUnit unit;
  final DateTime? resetsAt;
  final bool isUnmetered;
  final DateTime updatedAt;

  ProviderQuota({
