/// Human-readable summary lines for a CLI report.
List<String> summaryLines() {
  final droppedTotal = droppedByType.values.fold<int>(0, (a, b) => a + b);
  final droppedBytesTotal = droppedBytesByType.values.fold<int>(
    0,
    (a, b) => a + b,
