String? topLevelTimestampValue(String line) {
  final colon = _depth0TimestampColon(line);
  if (colon < 0) return null;
  return _stringValueAfter(line, colon);
}

/// The offset of the depth-0 colon whose key names `timestamp`, or -1.
/// A bounded char scan tracking string/escape/depth state — exact for
/// the writer-canonical field order and for any object whose top-level
/// timestamp key sits after nested payload fields.
int _depth0TimestampColon(String line) {
  var depth = 0;
  var inString = false;
  var escaped = false;
  for (var i = 0; i < line.length; i++) {
    final char = line[i];
    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (char == r'\') {
        escaped = true;
      } else if (char == '"') {
        inString = false;
      }
      continue;
    }
    switch (char) {
      case '"':
        inString = true;
      case '{' || '[':
        depth++;
      case '}' || ']':
        depth--;
      case ':':
        if (depth == 0 && _isTimestampKeyBefore(line, i)) return i;
    }
  }
  return -1;
}

/// Whether the key text immediately before the colon at [colon] is
/// exactly `"timestamp"` (the closest earlier occurrence ends at it).
bool _isTimestampKeyBefore(String line, int colon) {
  const key = '"timestamp"';
  return colon >= key.length && line.lastIndexOf(key, colon) == colon - key.length;
}

/// The JSON string value following the depth-0 colon at [colon] (the
/// scanner already proved the key names timestamp). Null when the value
/// is not a string or the line is torn mid-value.
String? _stringValueAfter(String line, int colon) {
  var j = colon + 1;
  while (j < line.length && line[j] == ' ') {
    j++;
  }
  if (j >= line.length || line[j] != '"') return null;
  final valueStart = ++j;
  while (j < line.length) {
    final valueChar = line[j];
    if (valueChar == r'\') {
      j += 2;
      continue;
    }
    if (valueChar == '"') break;
    j++;
  }
  if (j >= line.length || line[j] != '"') return null; // torn line
  return line.substring(valueStart, j);
}

