String? topLevelTimestampValue(String line) {
  String? result;
  var depth = 0;
  var inString = false;
  var escaped = false;
  for (var i = 0; i < line.length; i++) {
    final char = line[i];
    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (char == r'\') {
        escaped = true;
      } else if (char == '"') {
        inString = false;
      }
      continue;
    }
    switch (char) {
      case '"':
        inString = true;
      case '{' || '[':
        depth++;
      case '}' || ']':
        depth--;
      case ':':
        if (depth != 0) continue;
        // A depth-0 colon: the key just ended. Does it name timestamp?
        final keyEnd = line.lastIndexOf('"timestamp"', i);
        if (keyEnd < 0 || keyEnd != i - '"timestamp"'.length) continue;
        // The value starts after the colon (whitespace skipped).
        var j = i + 1;
        while (j < line.length && line[j] == ' ') {
          j++;
        }
        if (j >= line.length || line[j] != '"') return null;
        final valueStart = ++j;
        var closed = false;
        while (j < line.length) {
          final valueChar = line[j];
          if (valueChar == r'\') {
            j += 2;
            continue;
          }
          if (valueChar == '"') {
            closed = true;
            break;
          }
          j++;
        }
        if (!closed || j > line.length) return null; // torn line
        result = line.substring(valueStart, j);
        return result;
    }
  }
  return result;
}

